public static METCatchWeightOnHandResponse newFromParameters(METProcessingStatus _result, Description255 _message, ExecutionNameInventOnhand _executionName)
{
    METCatchWeightOnHandResponse response = new METCatchWeightOnHandResponse();

    response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
